contracts/DonationRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IFlameBornToken {
    function mintAfterValidation(address to, uint256 amount, string calldata interventionProof) external;
    function rewardYouthAction(address youth, uint256 amount, string calldata actionType) external;
}

interface IHealthActorRegistry {
    function actors(address actor) external view returns (bool verified, string memory segment, uint256 successCount, uint256 upgradeLevel);
    function recordIntervention(address facility, string calldata proof, uint256 successIncrement) external;
}

contract DonationRouter is AccessControl, ReentrancyGuard {
    bytes32 public constant VALIDATOR_ROLE = keccak256("VALIDATOR_ROLE");
    bytes32 public constant CONFIGURER_ROLE = keccak256("CONFIGURER_ROLE");

    IFlameBornToken public flbToken;
    IHealthActorRegistry public registry;

    uint256 public totalUnvalidatedEscrowedAmount;

    struct Escrow {
        address donor;
        address facility;
        uint256 amount;
        bool validated;
        uint48 timestamp;
    }

    Escrow[] public escrows;
    address public treasury;

    uint256 public validationTimeout = 90 days;

    event DonationEscrowed(uint256 indexed escrowId, address indexed donor, address indexed facility, uint256 amount);
    event InterventionValidated(uint256 indexed escrowId, address indexed facility, string proof, uint256 allocatedToFacility, uint256 allocatedToTreasury, uint256 remainingDust);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event ValidationTimeoutUpdated(uint256 indexed oldTimeout, uint256 indexed newTimeout);
    event DonationReclaimed(uint256 indexed escrowId, address indexed donor, uint256 amount);

    constructor(address _token, address _registry, address _treasury) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(VALIDATOR_ROLE, msg.sender);
        _grantRole(CONFIGURER_ROLE, msg.sender);

        require(_token != address(0), "DR: Invalid token address");
        require(_registry != address(0), "DR: Invalid registry address");
        require(_treasury != address(0), "DR: Invalid treasury address");

        flbToken = IFlameBornToken(_token);
        registry = IHealthActorRegistry(_registry);
        treasury = _treasury;
    }

    function donate(address facility) external payable nonReentrant {
        (bool verified, , , ) = registry.actors(facility);
        require(verified, "DR: Facility is not verified by HealthActorRegistry");
        require(msg.value > 0, "DR: Donation amount must be greater than zero");
        require(facility != address(0), "DR: Facility address cannot be zero");

        uint256 escrowId = escrows.length;
        escrows.push(Escrow({
            donor: msg.sender,
            facility: facility,
            amount: msg.value,
            validated: false,
            timestamp: uint48(block.timestamp)
        }));

        totalUnvalidatedEscrowedAmount += msg.value;

        emit DonationEscrowed(escrowId, msg.sender, facility, msg.value);
    }

    /**
     * @dev Allows an authorized VALIDATOR_ROLE to validate an intervention.
     * Upon validation, funds are released to the facility and treasury,
     * and FLB tokens are minted to the donor.
     * @param escrowId The ID of the escrowed donation to validate.
     * @param proof A string providing proof of the intervention (e.g., IPFS hash).
     * @param successUnits The measure of success for the intervention, recorded in the registry.
     */
    function validateIntervention(
        uint256 escrowId,
        // Changed to 'calldata' for optimization
        string calldata proof, 
        uint256 successUnits
    ) external onlyRole(VALIDATOR_ROLE) nonReentrant {
        require(escrowId < escrows.length, "DR: Invalid escrow ID");
        Escrow storage escrow = escrows[escrowId];
        require(!escrow.validated, "DR: Escrow already validated");
        require(bytes(proof).length > 0, "DR: Proof cannot be empty");

        escrow.validated = true;
        totalUnvalidatedEscrowedAmount -= escrow.amount;

        // 1. Record intervention in the HealthActorRegistry
        registry.recordIntervention(escrow.facility, proof, successUnits);

        // 2. Allocate funds based on V2 percentages
        // Optimized variable usage to reduce stack depth
        uint256 totalEscrowAmount = escrow.amount;
        uint256 toFacility; // Declare without assignment
        uint256 totalToTreasury; // Declare without assignment
        uint256 remainingDust; // Declare without assignment

        // Perform calculations
        toFacility = (totalEscrowAmount * 70) / 100;
        totalToTreasury = (totalEscrowAmount * 30) / 100; // Directly sum up 10+10+5+5 = 30% for treasury

        // If you need the individual guardian/platform/emergency/scrolls values later,
        // you would calculate them, but for the transfer to treasury, this single sum is sufficient.
        // uint256 toGuardians = (totalEscrowAmount * 10) / 100;
        // uint256 toPlatform = (totalEscrowAmount * 10) / 100;
        // uint256 toEmergency = (totalEscrowAmount * 5) / 100;
        // uint256 toScrolls = (totalEscrowAmount * 5) / 100;
        // totalToTreasury = toGuardians + toPlatform + toEmergency + toScrolls;

        remainingDust = totalEscrowAmount - toFacility - totalToTreasury;

        // 3. Fund transfers using .call for robustness
        (bool facilitySuccess, ) = payable(escrow.facility).call{value: toFacility}("");
        require(facilitySuccess, "DR: Facility ETH transfer failed");

        (bool treasurySuccess, ) = payable(treasury).call{value: totalToTreasury}("");
        require(treasurySuccess, "DR: Treasury ETH transfer failed");

        if (remainingDust > 0) {
            (bool dustSuccess, ) = payable(treasury).call{value: remainingDust}("");
            require(dustSuccess, "DR: Remaining dust transfer to treasury failed");
        }

        // 4. Mint FLB tokens to donor (post-validation)
        flbToken.mintAfterValidation(escrow.donor, totalEscrowAmount, proof);

        emit InterventionValidated(escrowId, escrow.facility, proof, toFacility, totalToTreasury, remainingDust);
    }

    function reclaimDonation(uint256 escrowId) external nonReentrant {
        require(escrowId < escrows.length, "DR: Invalid escrow ID");
        Escrow storage escrow = escrows[escrowId];
        require(msg.sender == escrow.donor, "DR: Only donor can reclaim");
        require(!escrow.validated, "DR: Escrow already validated, cannot reclaim");
        require(block.timestamp >= escrow.timestamp + validationTimeout, "DR: Validation timeout not reached");

        escrow.validated = true;
        totalUnvalidatedEscrowedAmount -= escrow.amount;

        (bool success, ) = payable(escrow.donor).call{value: escrow.amount}("");
        require(success, "DR: Failed to reclaim donation");

        emit DonationReclaimed(escrowId, escrow.donor, escrow.amount);
    }

    function rewardYouth(
        address youth,
        uint256 amount,
        string memory actionType
    ) external onlyRole(VALIDATOR_ROLE) {
        require(youth != address(0), "DR: Youth address cannot be zero");
        require(amount > 0, "DR: Reward amount must be greater than zero");
        require(bytes(actionType).length > 0, "DR: Action type cannot be empty");

        flbToken.rewardYouthAction(youth, amount, actionType);
    }

    function updateTreasury(address newTreasury) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newTreasury != address(0), "DR: New treasury address cannot be zero");
        emit TreasuryUpdated(treasury, newTreasury);
        treasury = newTreasury;
    }

    function updateValidationTimeout(uint256 _newTimeout) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newTimeout > 0, "DR: Timeout must be greater than zero");
        emit ValidationTimeoutUpdated(validationTimeout, _newTimeout);
        validationTimeout = _newTimeout;
    }

    function recoverAccidentalEth() external onlyRole(DEFAULT_ADMIN_ROLE) nonReentrant {
        uint256 contractBalance = address(this).balance;
        uint256 recoverableBalance = contractBalance - totalUnvalidatedEscrowedAmount;

        require(recoverableBalance > 0, "DR: No accidental ETH to recover or all ETH is escrowed.");

        (bool success, ) = payable(msg.sender).call{value: recoverableBalance}("");
        require(success, "DR: Failed to recover accidental ETH");
    }

    receive() external payable {
        revert("DR: Direct Ether transfers not allowed. Use donate function.");
    }
}

contracts/FlameBornToken.sol.content:
// contracts/FlameBornTokenV3.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20}from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title FlameBornTokenV3
 * @notice Soulbound ERC20 token for identity-based, non-transferable incentives.
 * @dev Fully gas-optimized and protected with proper access control and validation.
 */
contract FlameBornTokenV3 is ERC20, ERC20Burnable, AccessControl, EIP712 {
    // === Custom Errors ===
    error ZeroAddress();
    error AlreadyRegistered();
    error NotRegistered();
    error InvalidProof();
    error ZeroAmount();
    error MintClosed();
    error TransferNotAllowed();

    // === Role Identifiers ===
    bytes32 public constant DAO_ROLE = keccak256("DAO_ROLE");
    bytes32 public constant VALIDATOR_ROLE = keccak256("VALIDATOR_ROLE");
    bytes32 public constant YOUTH_ROLE = keccak256("YOUTH_ROLE");
    bytes32 public constant ELDER_ROLE = keccak256("ELDER_ROLE");
    bytes32 public constant TRIBAL_COUNCIL_ROLE = keccak256("TRIBAL_COUNCIL_ROLE");

    // === Mappings ===
    mapping(address user => bool) private _soulbound;
    mapping(address user => string) private _africanID;
    mapping(address user => VerificationType) private _verificationMethod;
    mapping(address user => bool) private _africanVerified;
    mapping(bytes32 => bool) private _approvedBiometricHashes;
    mapping(address => uint256) private _verificationTimestamp;

    // === Verification Types ===
    enum VerificationType {
        NONE,
        TRIBAL_COUNCIL,
        BIOMETRIC,
        ANCESTRY_PROOF
    }

    // === Events ===
    event AfricanIDRegistered(address indexed account, string idHash);
    event MintedAfterValidation(address indexed to, uint256 amount, string proof);
    event YouthActionRewarded(address indexed youth, uint256 amount, string action);
    event SymbolicSoulprint(address indexed user, string hash, uint256 weight, address issuedBy);
    event ControlledMint(address indexed to, uint256 amount);
    event FLBBurned(uint256 amount);
    event AfricanIdentityVerified(address indexed user, VerificationType method);
    event BiometricHashApproved(bytes32 indexed hash);
    event BiometricHashRevoked(bytes32 indexed hash);

    // === State flags ===
    bool public initialMintComplete;

    /**
     * @notice Deploys FlameBornTokenV3 and mints initial supply to deployer.
     * @param initialSupply Initial supply (without decimals).
     */
    constructor(uint256 initialSupply)
        ERC20("FlameBorn Token", "FLB")
        EIP712("FlameBorn", "3.0.0")
    {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(DAO_ROLE, msg.sender);
        _grantRole(VALIDATOR_ROLE, msg.sender);
        _grantRole(YOUTH_ROLE, msg.sender);
        _grantRole(ELDER_ROLE, msg.sender);
        _grantRole(TRIBAL_COUNCIL_ROLE, msg.sender);

        // Auto-verify deployer as African
        _africanID[msg.sender] = "FOUNDER_ORIGIN_VERIFIED";
        _africanVerified[msg.sender] = true;
        _verificationMethod[msg.sender] = VerificationType.TRIBAL_COUNCIL;
        _verificationTimestamp[msg.sender] = block.timestamp;
        _soulbound[msg.sender] = true;
        emit AfricanIdentityVerified(msg.sender, VerificationType.TRIBAL_COUNCIL);

        if (initialSupply > 0) {
            _mint(msg.sender, initialSupply * (10 ** decimals()));
        }
    }

    /**
     * @dev Disables transfers except minting and burning.
     * Also enforces African origin verification for recipients.
     */
    function _transfer(address from, address to, uint256 value) internal virtual override {
        // Allow minting and burning as before
        if (from == address(0) || to == address(0)) {
            super._transfer(from, to, value);
            // Mark as soulbound when minting
            if (from == address(0) && !_soulbound[to]) {
                _soulbound[to] = true;
            }
            return;
        }

        // Allow transfer only if recipient is a soulbound flameborn user
        if (!_soulbound[to] || !_isAfrican(to)) {
            revert TransferNotAllowed();
        }

        super._transfer(from, to, value);
    }

    /**
     * @dev Hook that ensures soulbound status after minting.
     */
     /**
     * @dev Hook that ensures soulbound status after minting.
     * Overrides ERC20’s internal hook.
     */
    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    )
        internal
        virtual
        override
    {
        super._beforeTokenTransfer(from, to, amount);

        if (from == address(0) && !_soulbound[to]) {
            _soulbound[to] = true;
        }
    }

    /**
     * @notice Register a hashed African ID. One-time action.
     * @param idHash Keccak256 hash of user's identity data.
     * @dev This function is for a user to register their own identity hash. It does not grant verified status.
     */
    function registerIdentity(bytes32 idHash) public {
        if (bytes(_africanID[msg.sender]).length != 0) revert AlreadyRegistered(); // Checks the caller, not a 'user' parameter
        if (idHash == bytes32(0)) revert InvalidProof();

        _africanID[msg.sender] = Strings.toHexString(uint256(idHash));
        emit AfricanIDRegistered(msg.sender, Strings.toHexString(uint256(idHash)));
    }

    /**
     * @notice Mint FLB tokens after verification by validator.
     */
    function mintAfterValidation(address to, uint256 amount, string calldata proof)
        external
        onlyRole(VALIDATOR_ROLE)
    {
        if (to == address(0)) revert ZeroAddress();
        if (!_isAfrican(to)) revert NotRegistered();
        if (amount == 0) revert ZeroAmount();
        if (bytes(proof).length == 0) revert InvalidProof();

        _mint(to, amount);
        emit MintedAfterValidation(to, amount, proof);
    }

    /**
     * @notice Mint tokens to reward youth participation.
     */
    function rewardYouthAction(address youth, uint256 amount, string calldata action)
        external
        onlyRole(YOUTH_ROLE)
    {
        if (youth == address(0)) revert ZeroAddress();
        if (!_isAfrican(youth)) revert NotRegistered();
        if (amount == 0) revert ZeroAmount();
        if (bytes(action).length == 0) revert InvalidProof();

        // African region bonus (add 10% bonus for continental initiatives)
        string memory regionCode = Strings.toHexString(uint256(keccak256(abi.encodePacked(_africanID[youth]))), 2);
        if (keccak256(abi.encodePacked(regionCode)) == keccak256(abi.encodePacked("0x"))) {
            amount = amount + (amount / 10); // 10% bonus
        }

        _mint(youth, amount);
        emit YouthActionRewarded(youth, amount, action);
    }

    /**
     * @notice Burn tokens from a user.
     */
    function burn(address from, uint256 amount) external onlyRole(DAO_ROLE) {
        if (from == address(0)) revert ZeroAddress();
        _burn(from, amount);
        emit FLBBurned(amount);
    }

    /**
     * @notice One-time minting for ecosystem bootstrapping.
     */
    function controlledMint(address to, uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (to == address(0)) revert ZeroAddress();
        if (initialMintComplete) revert MintClosed();

        _mint(to, amount);
        initialMintComplete = true;
        if (!_soulbound[to]) _soulbound[to] = true;

        emit ControlledMint(to, amount);
    }

    /**
     * @notice Issue symbolic metadata-only soulprint (non-token reward).
     */
    function issueSoulprint(address user, string calldata soulHash, uint256 weight)
        external
        onlyRole(DAO_ROLE)
    {
        if (!_isAfrican(user)) revert NotRegistered();
        if (bytes(soulHash).length == 0) revert InvalidProof();

        emit SymbolicSoulprint(user, soulHash, weight, msg.sender);
    }

    /**
     * @notice Get registered African ID hash.
     */
    function getAfricanID(address account) external view returns (string memory idHash) {
        idHash = _africanID[account];
    }

    /**
     * @notice Check if an address has been verified as African origin
     * @param user Address to check
     * @return verified Whether the address is verified as African
     */
    function isAfricanOrigin(address user) public view returns (bool) {
        return _africanVerified[user];
    }

    /**
     * @notice Get verification method used for an address
     * @param user Address to check
     * @return method Verification method used
     */
    function getVerificationMethod(address user) external view returns (VerificationType) {
        return _verificationMethod[user];
    }

    /**
     * @notice Verify African origin through tribal council approval
     * @param user Address to verify
     * @param africanIdHash African ID hash for the user
     */
    function verifyByTribalCouncil(address user, string calldata africanIdHash) 
        external 
        onlyRole(TRIBAL_COUNCIL_ROLE)
    {
        if (user == address(0)) revert ZeroAddress();
        if (bytes(africanIdHash).length == 0) revert InvalidProof();

        _africanID[user] = africanIdHash;
        _africanVerified[user] = true;
        _verificationMethod[user] = VerificationType.TRIBAL_COUNCIL;
        _verificationTimestamp[user] = block.timestamp;

        emit AfricanIdentityVerified(user, VerificationType.TRIBAL_COUNCIL);
    }

    /**
     * @notice Approve a biometric hash for verification
     * @param biometricHash Hash of approved biometric data
     */
    function approveBiometricHash(bytes32 biometricHash) 
        external 
        onlyRole(VALIDATOR_ROLE) 
    {
        if (biometricHash == bytes32(0)) revert InvalidProof();

        _approvedBiometricHashes[biometricHash] = true;
        emit BiometricHashApproved(biometricHash);
    }

    /**
     * @notice Revoke an approved biometric hash
     * @param biometricHash Hash to revoke
     */
    function revokeBiometricHash(bytes32 biometricHash) 
        external 
        onlyRole(VALIDATOR_ROLE) 
    {
        if (biometricHash == bytes32(0)) revert InvalidProof();

        _approvedBiometricHashes[biometricHash] = false;
        emit BiometricHashRevoked(biometricHash);
    }

    /**
     * @notice Verify African origin through biometric proof
     * @param africanIdHash African ID hash for the user
     * @param biometricHash Biometric data hash
     * @param signature Validator signature
     */
    function verifyByBiometric(
        string calldata africanIdHash,
        bytes32 biometricHash,
        bytes calldata signature
    ) external {
        if (bytes(africanIdHash).length == 0) revert InvalidProof();
        if (biometricHash == bytes32(0)) revert InvalidProof();

        // Verify the biometric hash is approved
        if (!_approvedBiometricHashes[biometricHash]) revert InvalidProof();

        // Verify validator signature
        bytes32 message = keccak256(abi.encodePacked(msg.sender, biometricHash, africanIdHash));
        bytes32 ethSignedHash = ECDSA.toEthSignedMessageHash(message);
        address signer = ECDSA.recover(ethSignedHash, signature);

        // Confirm signer is a validator
        if (!hasRole(VALIDATOR_ROLE, signer)) revert InvalidProof();

        // Register verification
        _africanID[msg.sender] = africanIdHash;
        _africanVerified[msg.sender] = true;
        _verificationMethod[msg.sender] = VerificationType.BIOMETRIC;
        _verificationTimestamp[msg.sender] = block.timestamp;

        emit AfricanIdentityVerified(msg.sender, VerificationType.BIOMETRIC);
    }

    /**
     * @notice Verify African origin through ancestry proof
     * @param user Address to verify
     * @param africanIdHash African ID hash for the user
     * @param ancestryProof Proof of African ancestry
     */
    function verifyByAncestryProof(
        address user,
        string calldata africanIdHash,
        bytes calldata ancestryProof
    ) external onlyRole(ELDER_ROLE) {
        if (user == address(0)) revert ZeroAddress();
        if (bytes(africanIdHash).length == 0) revert InvalidProof();
        if (ancestryProof.length == 0) revert InvalidProof();

        // In production, this would verify a zero-knowledge proof
        // For now, we trust the elder's verification

        _africanID[user] = africanIdHash;
        _africanVerified[user] = true;
        _verificationMethod[user] = VerificationType.ANCESTRY_PROOF;
        _verificationTimestamp[user] = block.timestamp;

        emit AfricanIdentityVerified(user, VerificationType.ANCESTRY_PROOF);
    }

    /**
     * @notice Returns number of decimals (18).
     */
    function decimals() public pure override returns (uint8) {
        return 18;
    }

    /**
     * @dev Check if a user has registered and verified their African ID.
     */
    function _isAfrican(address user) internal view returns (bool) {
        return bytes(_africanID[user]).length != 0 && _africanVerified[user];
    }
}

